insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-field-today', 'Your Today list', 'Clock in with your shift, then one list in order: each car and time is one card with its add-ons, clean check and photos.', array['field/my-jobs', 'field/a-handover', 'field/a-return']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-today'), 1, 'One list, in order', '[{"caption":"Four tabs","say":"The portal has four tabs: Today, My shifts, My pay and Training. Sales shows too if you asked to do sales.","visual":{"kind":"list","heading":"The tabs","items":["Today","My shifts","My pay","Training"]}},{"caption":"Clock in first","say":"Today opens with your shift. Press Clock in when you start: the phone shares where you are at that moment only.","visual":{"kind":"title","heading":"Clock in","text":"With your shift, at the start"}},{"caption":"The order of the work","say":"The list follows the day: pickups and returns at their time, onboarding prep, then cars to clean, cars needing service, and listing photos when you have spare time.","visual":{"kind":"steps","heading":"The order","items":["Pickups and returns","Onboarding prep","Cars to clean","Cars needing service","Listing photos in spare time"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-today'), 2, 'One card for each car and time', '[{"caption":"Everything for that car","say":"A pickup card holds the clean check, the add-ons to put in the car and the pickup itself. You never open three pages for one car.","visual":{"kind":"list","heading":"A pickup card","items":["Clean check: tick and photo","Add-ons: tick each one in the car","The pickup photos and handover"]}},{"caption":"One big button","say":"Each card has one big button: the next thing to do. It changes as you go.","visual":{"kind":"rule","heading":"One button","text":"Press the big button on the card: it is always the next step.","tone":"ok"}},{"caption":"Add-ons stop the pickup","say":"The pickup cannot be finished until every add-on is ticked as in the car. If the trip must go ahead without it, ask an Admin to override.","visual":{"kind":"rule","heading":"Add-ons first","text":"Child seat not in the car: the pickup waits, or an Admin overrides.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-today'), 3, 'Clean checks and clocking out', '[{"caption":"Before and after","say":"Every car is checked clean before each pickup and after each return: tick it and take a photo. Not clean: say what.","visual":{"kind":"steps","heading":"Clean check","items":["Look over the car","Tick clean","Take the photo"]}},{"caption":"Clock out","say":"Clock out shows what is still open. Each must-do still open needs a reason, and Fleet is told.","visual":{"kind":"chat","lines":[{"who":"you","text":"The renter is two hours late, Fleet knows."},{"who":"app","text":"Reason saved. Fleet has a To do."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-today'), 1, 'What is on one card?', '["Only the pickup photos","Everything for one car and time: clean check, add-ons and the pickup","All the cars of the day","Your hours"]'::jsonb, 1, 'Each car and time is one card.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-today'), 2, 'The child seat is not in the car yet. Can you finish the pickup?', '["Yes","No: tick it once it is in the car, or ask an Admin to override","Only after the return","Only Finance decides"]'::jsonb, 1, 'Add-ons stop the pickup until ticked or overridden.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-today'), 3, 'When do you do a clean check?', '["Once a month","Before each pickup and after each return, with a photo","Only when the renter asks","Never"]'::jsonb, 1, 'Before every pickup and after every return.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-today'), 4, 'You clock out with a return not done. What happens?', '["Nothing","You give a reason for it and Fleet is told","Your hours are lost","The return is cancelled"]'::jsonb, 1, 'Open must-dos need a reason; Fleet gets a To do.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-today'), 5, 'You have spare time between jobs. What is on the list for it?', '["Nothing","Cars to clean, cars needing service, and listing photos","Other people''s pickups","The renter''s paperwork"]'::jsonb, 1, 'The spare-time cards come after the must-dos.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'field', (select id from academy_sections where slug = 'new-r35-field-today'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'field' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-field-add', 'The Add button: money spent, service, photos and problems', 'Record gas, a wash or parts right away with the receipt, and any service done on a car; Finance and Fleet are told automatically.', array['field/my-jobs', 'field/report-rentals-referrals-and-profile']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-add'), 1, 'Money spent', '[{"caption":"Right away","say":"Spent money for the company? Press Add, then Money spent: what it was, the amount, the car, the booking, and a photo of the receipt.","visual":{"kind":"steps","heading":"Money spent","items":["What it was for","The amount","The car and booking","The receipt photo"]}},{"caption":"What happens next","say":"Finance approves it and pays it back if you used your own money. No receipt yet: you get a To do until you add it.","visual":{"kind":"money","heading":"Example","rows":[["Gas","$45.00"],["HST","$5.85"]],"total":"$50.85"}},{"caption":"Keep the receipt","say":"Take the receipt photo on the spot. A missing receipt stays on your To do list.","visual":{"kind":"rule","heading":"Receipt","text":"Photo of the receipt every time.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-add'), 2, 'Service and repairs', '[{"caption":"Record it on the car","say":"After a service or repair: Add, then Service record. What was done, where, the odometer, the cost and a photo of the invoice.","visual":{"kind":"list","heading":"A service record","items":["What was done","Where","Odometer (km)","Cost","Invoice photo"]}},{"caption":"Automatic","say":"The car''s maintenance timers reset, the expense is made on the car, and Fleet and Finance each get an alert and a To do.","visual":{"kind":"rule","heading":"Nothing else to do","text":"Fleet and Finance are told automatically.","tone":"ok"}},{"caption":"Photos and problems","say":"Add also takes photos of a car, and reports a problem: damage, a warning light, a ticket or lost property.","visual":{"kind":"list","heading":"Also on Add","items":["Photos of a car","A problem with a car"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-add'), 1, 'You bought gas for a car. What do you do?', '["Keep the receipt for later","Add, Money spent, with the amount, the car and a receipt photo","Tell the renter","Nothing"]'::jsonb, 1, 'Record it right away from the phone.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-add'), 2, 'You forgot the receipt photo. What happens?', '["The money is lost","You get a To do until you add it","Finance deletes it","Nothing"]'::jsonb, 1, 'A missing receipt is a To do.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-add'), 3, 'What does a service record need?', '["Only the cost","What, where, the odometer, the cost and the invoice photo","The renter''s name","Nothing"]'::jsonb, 1, 'All five, so the car and the money are right.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-add'), 4, 'Who is told about a service you record?', '["Nobody","Fleet and Finance, automatically","The renter","Only you"]'::jsonb, 1, 'Both get an alert and a To do.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-add'), 5, 'A car you see has a warning light on. Where do you report it?', '["Text a friend","Add, then A problem with a car","Nowhere","On the renter''s booking page"]'::jsonb, 1, 'Add also reports a problem with a car.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'field', (select id from academy_sections where slug = 'new-r35-field-add'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'field' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-field-shifts-pay', 'Shifts and pay', 'Claim shifts, give one up with a reason, swap with someone, and enter your pay details before you are paid.', array['field/my-hours-and-pay']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-shifts-pay'), 1, 'My shifts', '[{"caption":"Claim","say":"Open shifts are on My shifts. Press Claim to take one. Jobs are only given to people on a shift.","visual":{"kind":"title","heading":"Claim a shift","text":"Jobs go to people on a shift"}},{"caption":"Give one up","say":"Cannot work a shift? Give it up with a reason. It is offered to everyone free then, and the first to claim takes it. Under 24 hours before the start, it is marked late on your record.","visual":{"kind":"rule","heading":"Give up early","text":"Under 24 hours is a late give-up.","tone":"warn"}},{"caption":"Swap","say":"Swap with someone: choose your shift and theirs. They accept or decline on their phone.","visual":{"kind":"steps","heading":"A swap","items":["Your shift","Their shift","They accept"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-shifts-pay'), 2, 'My pay', '[{"caption":"Pay details first","say":"Before your first pay: your full legal name, email, phone, SIN and a photo of a void cheque, on My pay.","visual":{"kind":"list","heading":"Pay details","items":["Full legal name","Email and phone","SIN","Void cheque"]}},{"caption":"Private","say":"Your SIN is kept encrypted. Only Finance and Admin can see it, and every time they look it is recorded. You see only the last three digits.","visual":{"kind":"rule","heading":"Your SIN","text":"Shown as ***-***-123.","tone":"ok"}},{"caption":"Hours and statements","say":"My pay shows this period''s hours and your pay statements.","visual":{"kind":"title","heading":"My pay","text":"Hours and statements"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-shifts-pay'), 1, 'You cannot work tomorrow''s shift. What do you do?', '["Just do not come","Give it up on My shifts with a reason, as early as you can","Text a friend","Tell the renter"]'::jsonb, 1, 'It is then offered to everyone free.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-shifts-pay'), 2, 'When is a give-up marked late?', '["Never","Under 24 hours before the start","After the shift","Only on weekends"]'::jsonb, 1, 'Under 24 hours is flagged on your record.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-shifts-pay'), 3, 'Who can see your full SIN?', '["Everyone","Only Finance and Admin, and each view is recorded","Other field staff","Renters"]'::jsonb, 1, 'Encrypted, Finance and Admin only.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-shifts-pay'), 4, 'What do you need before your first pay?', '["Nothing","Full legal name, email, phone, SIN and a void cheque","Only your email","A selfie"]'::jsonb, 1, 'The pay details step on My pay.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-shifts-pay'), 5, 'A shift you gave up is offered to others. Who gets it?', '["Fleet picks at random","The first person to claim it","Nobody","You, again"]'::jsonb, 1, 'First to claim takes it.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'field', (select id from academy_sections where slug = 'new-r35-field-shifts-pay'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'field' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-field-renter-help', 'Helping a renter on the spot', 'Take a payment or the deposit by link, QR or the card reader, check the licence in person and get the agreement signed. Refunds stay with Finance.', array['field/a-handover']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-renter-help'), 1, 'Payment and deposit', '[{"caption":"From the card or a search","say":"On a pickup card, or any booking you find by name, phone or booking number, press Help the renter.","visual":{"kind":"title","heading":"Help the renter","text":"From a card or a search"}},{"caption":"Three ways to pay","say":"Send a pay link by text or email, show a QR code they scan with their own phone, or use the card reader when you have it. Never type a card number.","visual":{"kind":"list","heading":"Ways to pay","items":["Pay link by text or email","QR code on your phone","The card reader"]}},{"caption":"Refunds","say":"Refunds and voids stay with Finance and Admin. Tell the renter Finance will handle it.","visual":{"kind":"rule","heading":"No refunds in the field","text":"Finance or an Admin.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-renter-help'), 2, 'Licence and signature', '[{"caption":"Check the licence","say":"Take the licence photos with the licence reader, then check the name and date of birth match and that the person matches the photo.","visual":{"kind":"steps","heading":"Check the licence","items":["Front and back photos","Name and date of birth match","The person matches the photo"]}},{"caption":"Signature","say":"Send the signing link, or let them sign on your phone in person with their own finger. Paper is the last resort, with a photo, as the rules say.","visual":{"kind":"list","heading":"Signature","items":["Signing link","Sign on this phone","Paper photo as the last resort"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-renter-help'), 1, 'A renter wants to pay at the car. What do you never do?', '["Send a pay link","Show the QR","Type their card number","Use the card reader"]'::jsonb, 2, 'The renter enters the card themselves; you never type card numbers.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-renter-help'), 2, 'A renter asks for a refund. What do you do?', '["Refund it","Tell them Finance or an Admin handles refunds","Give cash","Cancel the booking"]'::jsonb, 1, 'Refunds and voids stay with Finance and Admin.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-renter-help'), 3, 'What do you check on the licence in person?', '["Only the colour","Name and date of birth match, and the person matches the photo","Nothing","The address only"]'::jsonb, 1, 'Match the name, the date of birth and the face.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-renter-help'), 4, 'The renter wants to pay on their own phone at the car. What do you show them?', '["Your card","The QR code: they scan it and pay on their phone","The booking number only","Nothing"]'::jsonb, 1, 'The QR opens the secure pay page on their phone.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-renter-help'), 5, 'How can the agreement be signed on the spot?', '["You sign for them","They sign on your phone with their own finger, or by the signing link","By phone call","It cannot"]'::jsonb, 1, 'Always the renter''s own signature.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'field', (select id from academy_sections where slug = 'new-r35-field-renter-help'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'field' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-field-prep', 'Onboarding prep of a new car', 'Fleet gives you the prep of a car joining the fleet: safety certificate, maintenance, cleaning, photos, plates and the tracker.', array['field/photo-shoots']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-prep'), 1, 'A prep card', '[{"caption":"On your Today","say":"Onboarding prep shows on your Today on the day Fleet chose, one card for the car with its own checklist.","visual":{"kind":"list","heading":"Prep items","items":["Safety certificate","Maintenance and repairs","Cleaning","Listing photos","Plates and permit","Tracker"]}},{"caption":"Upload as you go","say":"Each item is ticked with its upload: the safety certificate PDF or photo, the invoices. Costs go through Add, the same as any money spent.","visual":{"kind":"rule","heading":"Uploads","text":"The safety certificate needs its upload and expiry date.","tone":"warn"}},{"caption":"Done","say":"When every item is done, the owner''s onboarding checklist is updated and Fleet is told.","visual":{"kind":"title","heading":"Prep done","text":"The checklist updates by itself"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-prep'), 1, 'Where do you see onboarding prep?', '["By email only","On your Today, on the day Fleet chose","On the owner portal","Nowhere"]'::jsonb, 1, 'It is a card on your Today.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-prep'), 2, 'What does the safety certificate item need?', '["Nothing","The certificate upload and its expiry date","A phone call","The renter''s name"]'::jsonb, 1, 'Upload it with its expiry.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-prep'), 3, 'You paid for a repair during prep. How is it recorded?', '["Not at all","Through Add, the same as any money spent or service record","On paper","By text to Fleet"]'::jsonb, 1, 'The same Add flows.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-prep'), 4, 'What happens when every prep item is done?', '["Nothing","The owner''s onboarding checklist updates and Fleet is told","The car is sold","The renter is told"]'::jsonb, 1, 'The checklist updates by itself.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-field-prep'), 5, 'Can Fleet give you prep on a day you have no shift?', '["Yes","No: only on a day you hold a shift","Only on weekends","Only for Admins"]'::jsonb, 1, 'Shift rules apply to prep too.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'field', (select id from academy_sections where slug = 'new-r35-field-prep'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'field' on conflict (path_code, section_id) do nothing;
