-- 0932: the academy's field path gets the new field portal and duties (Release 35, part X; docs/changes/2026-11-08-r35-field-portal.md).
-- No applied migration is edited. Five sections on the field path (supabase/seed/academy/r35x.mjs, generated below): the Today list,
-- the Add button (money spent and service records), shifts and pay, helping a renter on the spot, and onboarding prep. Field staff
-- who had passed every section of their paths keep a week before the new sections hold them (as 0731 and 0802 did); nothing is reset.
create temp table r35x_done on commit drop as
select distinct e.user_id from academy_enrollments e where e.path_code = 'field' and app.academy_done(e.user_id);

-- ACADEMY 0932 START (generated by supabase/seed/0932_gen_academy.mjs from supabase/seed/academy/r35x.mjs; do not edit by hand)
-- ACADEMY 0932 END

update academy_enrollments e set lock_from = greatest(e.lock_from, now() + interval '7 days')
  from r35x_done d where e.user_id = d.user_id and e.gate;
